"""End-to-end morphological watershed segmentation and artifact export."""

from dataclasses import dataclass
from pathlib import Path

import imageio.v3 as iio
import numpy as np
from skimage.color import label2rgb
from skimage.filters import gaussian, threshold_otsu
from skimage.segmentation import watershed

from watershed_btl.morphology import binary_closing, binary_opening, make_markers


@dataclass(frozen=True)
class SegmentationResult:
    """Intermediate and final arrays generated by :func:`segment`."""

    binary_mask: np.ndarray
    distance_map: np.ndarray
    markers: np.ndarray
    labels: np.ndarray
    overlay: np.ndarray


def segment(
    image: np.ndarray,
    threshold: int | None = None,
    radius: int = 2,
    peak_fraction: float = 0.45,
) -> SegmentationResult:
    """Segment a two-dimensional grayscale image with marker-controlled watershed."""
    source = np.asarray(image)
    if source.ndim != 2:
        raise ValueError("image must be a two-dimensional grayscale array")

    denoised = gaussian(source, sigma=1.0, preserve_range=True)
    cutoff = threshold_otsu(denoised) if threshold is None else threshold
    binary_mask = denoised > cutoff
    binary_mask = binary_opening(binary_mask, radius=radius)
    binary_mask = binary_closing(binary_mask, radius=radius)
    distance_map, markers = make_markers(binary_mask, peak_fraction=peak_fraction)
    labels = watershed(-distance_map, markers, mask=binary_mask).astype(np.int32)
    overlay = label2rgb(labels, image=source, bg_label=0, kind="overlay")
    return SegmentationResult(
        binary_mask=binary_mask,
        distance_map=distance_map,
        markers=markers,
        labels=labels,
        overlay=overlay,
    )


def _to_uint8(array: np.ndarray) -> np.ndarray:
    """Scale a numeric image to an unsigned-byte PNG plane for display."""
    values = np.asarray(array, dtype=np.float64)
    maximum = values.max(initial=0.0)
    if maximum <= 0:
        return np.zeros(values.shape, dtype=np.uint8)
    return np.rint(values * (255.0 / maximum)).astype(np.uint8)


def save_stage_images(
    result: SegmentationResult,
    image: np.ndarray,
    output_dir: Path,
    stem: str,
) -> dict[str, Path]:
    """Write input and each pipeline stage as PNGs in ``output_dir``."""
    destination = Path(output_dir)
    destination.mkdir(parents=True, exist_ok=True)
    paths = {
        "input": destination / f"{stem}_input.png",
        "binary_mask": destination / f"{stem}_binary_mask.png",
        "distance_map": destination / f"{stem}_distance_map.png",
        "markers": destination / f"{stem}_markers.png",
        "labels": destination / f"{stem}_labels.png",
        "overlay": destination / f"{stem}_overlay.png",
    }
    iio.imwrite(paths["input"], np.asarray(image))
    iio.imwrite(paths["binary_mask"], result.binary_mask.astype(np.uint8) * 255)
    iio.imwrite(paths["distance_map"], _to_uint8(result.distance_map))
    iio.imwrite(paths["markers"], _to_uint8(result.markers))
    iio.imwrite(paths["labels"], _to_uint8(result.labels))
    iio.imwrite(paths["overlay"], _to_uint8(result.overlay))
    return paths
